async function refreshClients(force=false){if(force===true)notice('연결 상태 확인 중…');// A forced check also drops the remembered model lists on the host, so the lists are asked for after it.
const [data,models]=force===true?[await request('settings/refresh',{force:true}),await request('settings/models')]:await Promise.all([request('settings/refresh',{}),request('settings/models')]);clientCatalogs=models;$('clients').replaceChildren();if(data.owner_mcp){const reasons={covered_by_office:localized('Office에 이미 있음','already in Office'),runs_code_or_controls_computer:localized('코드 실행·PC 제어','runs code or controls the computer'),reads_local_files:localized('이 PC의 파일을 읽음','reads files on this computer'),not_reachable:localized('응답 없음','no answer'),no_read_tool:localized('읽기 도구 없음','no read tool'),other_computer:localized('Windows 쪽 프로그램','Windows-side program'),disabled:localized('꺼져 있음','turned off')},line=document.createElement('small');line.className='muted owner-mcp';line.dataset.i18nSkip='';line.textContent=localized('쓰던 MCP 서버 · 사용: ','Your MCP servers · used: ')+(data.owner_mcp.used.map(item=>item.server+' ('+item.tools.length+')').join(', ')||localized('없음','none'))+' · '+localized('제외: ','left out: ')+(data.owner_mcp.left_out.map(item=>item.server+' ('+(reasons[item.reason]||item.reason)+')').join(', ')||localized('없음','none'));queueMicrotask(()=>$('clients').append(line));}for(const client of data.clients){const card=document.createElement('div');card.className='client';card.id='client-'+client.id;if(client.environment?.found){const found=client.environment,line=document.createElement('small');line.className='muted client-environment';line.dataset.i18nSkip='';line.textContent=localized('기존 환경 ','Existing setup ')+((found.locations||[]).map(place=>place.config_home).join(' + ')||found.config_home)+' · '+localized('스킬 ','skills ')+found.skills.length+' · MCP '+found.mcp_servers.length+(found.mcp_servers.length?' ('+found.mcp_servers.slice(0,6).join(', ')+')':'')+' · '+localized('플러그인 ','plugins ')+found.plugins.length+' · '+localized('프로젝트 ','projects ')+found.projects+(found.default_model?' · '+localized('기본 모델 ','default model ')+found.default_model:'');line.title=found.skills.join(', ');queueMicrotask(()=>card.append(line));}const name=({codex:'Codex',claude:'Claude Code',opencode:'OpenCode',cursor:'Cursor',hermes:'Hermes'})[client.id],row=clientRow(name,client.reason==='wsl_native_client_not_found'?'설치 안 됨':labels[client.status],client.status==='ready'?'ok':['signed_out','expired','needs_login','challenge'].includes(client.status)?'warn':'idle',client.id),actions=row.querySelector('.cact');card.append(row);const output=document.createElement('div');output.className='device';output.hidden=true;output.id='flow-'+client.id;card.append(output);if(['signed_out','expired'].includes(client.status))for(const flow of [client.supported_login_flows.includes('device')?'device':client.supported_login_flows[0]].filter(Boolean)){const button=document.createElement('button');button.textContent='로그인';button.className='login-action';button.setAttribute('aria-label',client.id+' 로그인');button.onclick=()=>loginAction(client.id,flow);actions.append(button);}if(client.status==='ready')addClientManage(actions,client.id,name);const installation=bootstrapState?.clients?.find(item=>item.id===client.id);if(installation&&!installation.installed&&installation.managed_install){const install=document.createElement('button');install.textContent='설치';install.setAttribute('aria-label',name+' 설치');install.onclick=()=>installAction(client.id);actions.append(install);}$('clients').append(card);renderFlow(client.connection);}
  const codex=models.codex,listed=codex?.status==='available',prior=$('codex-model').value;
  const recommended=!state.configured&&modelScope==='global'&&!codexChoiceTouched&&listed&&codex.models.some(row=>row.id===preferredCodexId)?preferredCodexId:null;
  for(const id of ['codex','claude','opencode'])fillModels(id+'-model',models[id]?.models||[],id==='codex'&&recommended!==null?recommended:$(id+'-model').value);
  if(recommended&&!codexEffortTouched)$('codex-reasoning').value='low';
  const unsupported=listed&&Boolean(prior)&&!codex.models.some(row=>row.id===prior);
  fillRoleModels();$('catalog-state').textContent=localized('현재 확인: ','Checked: ')+['codex','claude','opencode'].map(id=>id+' '+(models[id]?.status==='available'?localized(models[id].models.length+'개',models[id].models.length+' models'):localized('목록 미확인','Catalog unverified'))).join(' · ')+(unsupported?state.configured?localized(' · 저장한 Codex 모델을 이 계정에서 쓸 수 없습니다. 목록에서 다시 선택하세요.',' · The saved Codex model is not in the current account catalog. Select a listed model.'):localized(' · 새 기본 Codex 모델은 현재 계정 목록에 없습니다. 지원 모델을 선택하세요.',' · The new default Codex model is not in this account catalog. Select a listed model.'):recommended?localized(' · 요청한 Codex 6.1 Sol을 현재 계정 목록에서 확인했습니다.',' · Requested Codex 6.1 Sol is listed for this account.'):!listed?localized(' · Codex 계정 지원 여부는 아직 확인되지 않았습니다.',' · Codex account availability has not been checked.'):'')+localized(' · Claude 목록은 계정 지원 확인이 아닙니다.',' · Claude choices do not prove account access.');notice('확인했습니다.');}
async function refreshModelChoices(){const models=await request('settings/models');clientCatalogs=models;for(const id of ['codex','claude','opencode'])fillModels(id+'-model',models[id]?.models||[],$(id+'-model').value);fillRoleModels();$('catalog-state').textContent=localized('CLI 업데이트 후 모델 목록을 새로 가져왔습니다. 선택은 그대로입니다. Claude 모델은 계정에 따라 쓸 수 없을 수 있습니다.','The model list was refreshed after the CLI update. Your selection is unchanged. Some Claude models may not be available to your account.');clientsLoaded=true;}
async function refreshApiModels(reset=false){const provider=$('api-provider').value,body={provider,api_base_url:$('api-base-url').value.trim()};if($('api-key').value.trim())body.api_key=$('api-key').value.trim();const current=reset?'':$('api-model-custom').value.trim()||$('api-model').value||(state.selection.api_provider===provider?state.selection.api_model:'');body.current=current;const catalog=await request('settings/models',body);if(provider!==$('api-provider').value||body.api_base_url!==$('api-base-url').value.trim())return;apiCatalog=catalog;apiCatalogProvider=provider;fillModels('api-model',catalog.models,catalog.status==='available'?catalog.selected||'':catalog.selected||current,'모델 선택');if(catalog.selected&&catalog.selected!==current)$('api-model-custom').value='';$('api-state').textContent=catalog.status==='available'?catalog.models.length+'개 모델 확인 · '+new Date(catalog.fetched_at).toLocaleString(window.officeLang==='ko'?'ko-KR':'en-GB'):(catalog.models.length?'키 입력 후 새로고침하면 최신 목록을 불러옵니다 · 기본 '+catalog.selected:'모델 목록을 확인하지 못했습니다. 저장된 선택은 유지됩니다.');}
function renderFlow(flow){const url=flow.auth_url||flow.device_url,tab=authWindows.get(flow.client_id);if(url&&tab&&!tab.closed){tab.location.replace(url);authWindows.delete(flow.client_id);}if(['completed','failed','unavailable'].includes(flow.state))closeAuthWindow(flow.client_id);for(const target of [$('flow-'+flow.client_id),$('agent-flow-'+flow.client_id)].filter(Boolean)){if(flow.state==='idle'||flow.state==='unavailable'&&flow.reason==='login_contract_unavailable'){target.hidden=true;target.replaceChildren();continue;}target.hidden=false;target.replaceChildren();const text=document.createElement('span');text.textContent=({starting:'인증 화면 준비 중…',waiting:url?'공식 인증 화면에서 인증을 마쳐주세요.':'인증 화면 준비 중…',completed:'로그인 완료 · 상태를 다시 확인합니다.',failed:'로그인을 완료하지 못했습니다. 로그인 버튼으로 다시 시도하세요.',unavailable:'설치는 유지됩니다. 다시 확인 후 로그인을 다시 누르세요.'})[flow.state]||flow.state;target.append(text);if(url){const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noreferrer';link.className='action-link';link.textContent='인증 열기';target.append(link);}if(flow.user_code){const code=document.createElement('code');code.textContent=flow.user_code;target.append(code);}}}
async function pollFlows(){try{const data=await request('settings/flows');data.flows.forEach(renderFlow);if(!data.flows.some(f=>['starting','waiting'].includes(f.state))){clearInterval(flowTimer);if(step===0)await refreshMcp();else if(step===2)await refreshClients(true);}}catch{clearInterval(flowTimer);}}
function appendActivity(event){const ko=window.officeLang==='ko',time=new Date(event.at).toLocaleTimeString(ko?'ko-KR':'en-GB',{hour12:false}),status=(ko?{running:'진행',success:'완료',warning:'확인 필요',error:'실패',info:'기록'}:{running:'running',success:'done',warning:'needs attention',error:'failed',info:'log'})[event.state]||(ko?'기록':'log'),message=window.officeText(event.message);if($('setup-log').dataset.empty==='true'){$('setup-log').textContent='';$('setup-log').dataset.empty='false';}$('setup-log').textContent+=time+' ['+event.area.toUpperCase()+' · '+status+'] '+message+'\\n';$('setup-log').scrollTop=$('setup-log').scrollHeight;$('tail-last').textContent=message;}
let maintenanceCatalogRefreshTimer;const activitySource=new EventSource('settings/activity');activitySource.onopen=()=>{$('tail-state').textContent='실시간 연결됨';};activitySource.onerror=()=>{$('tail-state').textContent='재연결 중';};activitySource.onmessage=message=>{const value=JSON.parse(message.data);if(value.kind==='snapshot'){$('setup-log').textContent='';$('setup-log').dataset.empty='false';if(value.events.length)value.events.forEach(appendActivity);else{$('setup-log').textContent='아직 연결 작업 기록이 없습니다.';$('setup-log').dataset.empty='true';}}else if(value.kind==='activity'){appendActivity(value.event);if(value.event.message==='CLI 업데이트 확인을 마쳤습니다. 모델 목록을 새로고침하세요.'){clearTimeout(maintenanceCatalogRefreshTimer);maintenanceCatalogRefreshTimer=setTimeout(()=>{if(!initialized||busy||step!==2){clientsLoaded=false;return;}void action(async()=>{await loadMaintenance();await refreshModelChoices();});},900);}}};
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>action(()=>show(Number(b.dataset.step))));
