async function initialize(){lockControls(true);$('retry-settings').hidden=true;notice('설정을 불러오는 중…');try{const [value,mcp,bootstrap]=await Promise.all([request('settings/status'),request('settings/mcp'),request('settings/bootstrap')]);state=value;mcpState=mcp;bootstrapState=bootstrap;initialized=true;populate();notice('');await action(async()=>{await show(location.hash==='#browsers'?1:!mcp.registered_count&&!state.computer.connected?0:!state.computer.connected?1:Math.min(4,Math.max(2,state.onboarding_step)));if(state.selection.mode==='api')await refreshApiModels();});}catch{initialized=false;lockControls(true);notice('설정을 불러오지 못했습니다. 다시 시도해 주세요.');$('retry-settings').hidden=false;}}
